import{_ as t,c as r,o as a,ag as o}from"./chunks/framework.B-XtCDNB.js";const d=JSON.parse('{"title":"5. Internal libgee","description":"5. Internal libgee Currently the vala compiler repository uses its own internal copy of libgee, located in vala/gee The copy was made to replace the use of GLib collections in the project (See git...","frontmatter":{},"headers":[],"relativePath":"contributor-guide/compiler-guide/05-00-internal-libgee.md","filePath":"contributor-guide/compiler-guide/05-00-internal-libgee.md","lastUpdated":1784474597000}'),i={name:"contributor-guide/compiler-guide/05-00-internal-libgee.md"};function l(n,e,s,g,c,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="_5-internal-libgee" tabindex="-1">5. Internal libgee <a class="header-anchor" href="#_5-internal-libgee" aria-label="Permalink to &quot;5. Internal libgee&quot;">​</a></h1><p>Currently the vala compiler repository uses its own internal copy of <a href="https://gitlab.gnome.org/GNOME/libgee" target="_blank" rel="noreferrer">libgee</a>, located in <a href="https://gitlab.gnome.org/GNOME/vala/-/tree/main/gee" target="_blank" rel="noreferrer"><code>vala/gee</code></a></p><p>The copy was made to replace the use of GLib collections in the project (<a href="https://gitlab.gnome.org/GNOME/vala/-/commit/5a32f9e2108feff5cdc997fd79303e5f4e9b6175" target="_blank" rel="noreferrer">See git commit 5a32f9e2</a>). Internal libgee contains a subset of the features from external libgee. Some features get backported over time.</p><p>There were issues preventing external libgee from being used in the compiler repository however, they have been resolved.</p><p>Work is in-progress to stop using a bundled version of libgee and use the external libgee library: <a href="https://gitlab.gnome.org/GNOME/vala/-/work_items/398" target="_blank" rel="noreferrer">https://gitlab.gnome.org/GNOME/vala/-/work_items/398</a></p>',5)])])}const f=t(i,[["render",l]]);export{d as __pageData,f as default};
